document.addEventListener('DOMContentLoaded',function(){const investmentSlider=document.getElementById('investmentSlider');const investmentInput=document.getElementById('investmentInput');const periodSlider=document.getElementById('periodSlider');const periodInput=document.getElementById('periodInput');const resultValue=document.getElementById('resultValue');function getInvestmentValue(){if(investmentInput){const text=investmentInput.textContent||investmentInput.innerText;return parseInt(text)||0}
return 0}
function getPeriodValue(){if(periodInput){const text=periodInput.textContent||periodInput.innerText;return parseInt(text)||0}
return 0}
function calculateResult(){const investment=getInvestmentValue();const period=getPeriodValue();const result=Math.round(investment*(1+period*0.07));const currencySpan=resultValue.querySelector('.calculator-currency');const currency=currencySpan?currencySpan.outerHTML:' <span class="calculator-currency">$</span>';resultValue.innerHTML=result+currency}
if(investmentSlider&&investmentInput){investmentSlider.addEventListener('input',function(){const currencySpan=investmentInput.querySelector('.calculator-currency');const currency=currencySpan?currencySpan.outerHTML:' <span class="calculator-currency">$</span>';investmentInput.innerHTML=this.value+currency;calculateResult()})}
if(periodSlider&&periodInput){periodSlider.addEventListener('input',function(){const currencySpan=periodInput.querySelector('.calculator-currency');const currency=currencySpan?currencySpan.outerHTML:' <span class="calculator-currency">días</span>';periodInput.innerHTML=this.value+currency;calculateResult()})}
if(resultValue){calculateResult()}
const calculator=document.querySelector('.calculator');const fixedLink=document.querySelector('.fixed-link');if(calculator&&fixedLink){function checkCalculatorVisibility(){const calculatorRect=calculator.getBoundingClientRect();const windowHeight=window.innerHeight;if(calculatorRect.top<windowHeight&&calculatorRect.bottom>0||calculatorRect.top<=0){fixedLink.classList.add('visible')}else if(calculatorRect.top>=windowHeight){fixedLink.classList.remove('visible')}}
checkCalculatorVisibility();window.addEventListener('scroll',checkCalculatorVisibility);window.addEventListener('resize',checkCalculatorVisibility)}})